if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['add'])){$id=(int)($_POST['product_id']??0);$qty=max(1,(int)($_POST['qty']??1));$st=$conn->prepare('SELECT id,name,price,stock FROM products WHERE id=?');$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();if($p&&$p['stock']>0){$_SESSION['cart']=$_SESSION['cart']??[];$_SESSION['cart'][$id]=min($p['stock'],(int)($_SESSION['cart'][$id]??0)+$qty);$_SESSION['flash']='Menu ditambahkan ke keranjang.';}else $_SESSION['flash']='Produk tidak tersedia.';header('Location: customer.php');exit;}
$products=$conn->query('SELECT * FROM products WHERE stock>0 ORDER BY category,name');require 'includes/header.php'; ?>
<div class="page-heading"><div><h1>Menu Phoenix Coffee</h1><p>Pilih kopi dan camilan favoritmu, <?= e($_SESSION['user']['name']) ?>.</p></div><a class="btn" href="keranjang.php">🛒 Keranjang (<?= array_sum($_SESSION['cart']??[]) ?>)</a></div>
<div class="product-grid customer-products"><?php if($products->num_rows):while($p=$products->fetch_assoc()): ?><form class="product-tile" method="post"><img class="tile-image" src="<?= e(product_image($p['name'],$p['category'])) ?>" alt="<?= e($p['name']) ?>"><div class="tile-name"><?= e($p['name']) ?></div><div class="tile-price"><?= rupiah($p['price']) ?></div><p style="font-size:11px;color:var(--muted)"><?= e($p['category']) ?> · Stok <?= (int)$p['stock'] ?></p><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><input type="number" name="qty" min="1" max="<?= (int)$p['stock'] ?>" value="1" style="width:100%;margin-bottom:8px;padding:8px;border:1px solid var(--line);border-radius:6px"><button class="btn" name="add" value="1" style="width:100%">Tambah ke Keranjang</button></form><?php endwhile;else: ?><div class="empty">Menu sedang tidak tersedia.</div><?php endif; ?></div>
